import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

/*
 * Thin, stable loader. All real code lives in main.js (generated by build.sh).
 * Importing with a cache-busting query lets us hot-reload main.js on
 * disable/enable without restarting GNOME Shell.
 */
export default class LvOSKExtension extends Extension {
    async enable() {
        try {
            this._mod = await import(`./main.js?v=${Date.now()}`);
            this._mod.enable();
        } catch (e) {
            console.error(`lvosk: failed to load main.js: ${e}`);
        }
    }

    disable() {
        try {
            if (this._mod)
                this._mod.disable();
        } catch (e) {
            console.error(`lvosk: disable error: ${e}`);
        }
        this._mod = null;
    }
}